      {w:"curtailing",p:"noun",ipa:"/kɜːˈteɪlɪŋ/",def:"the act of limiting something or making it shorter or smaller",tr:"cheklash / qisqartirish",ex:"Some fear the curtailing of internet freedom."},
      {w:"legitimate",p:"adjective",ipa:"/lɪˈdʒɪtɪmət/",def:"fair and acceptable; allowed by law",tr:"qonuniy / asosli",ex:"Most internet users have legitimate reasons to protect their privacy."},
      {w:"look out",p:"phrasal verb",ipa:"/ˌlʊk ˈaʊt/",def:"to be careful; to watch for something",tr:"ehtiyot bo'lmoq / kuzatmoq",ex:"Look out for suspicious emails."},
      {w:"privacy",p:"noun",ipa:"/ˈprɪvəsi/",def:"the state of being free from the attention of the public; freedom from people watching you",tr:"shaxsiy hayot daxlsizligi / maxfiylik",ex:"Tighter security could reduce our privacy."},
      {w:"do in",p:"phrasal verb",ipa:"/ˌduː ˈɪn/",def:"(here: as in 'what we do in cyberspace') to carry out an activity in a particular place; (informal) to kill somebody or make them very tired",tr:"...da qilmoq; (norasmiy) holdan toydirmoq",ex:"Governments want to watch what we do in cyberspace."},
      {w:"deny",p:"verb",ipa:"/dɪˈnaɪ/",def:"to refuse to let somebody have something; to say that something is not true",tr:"rad etmoq / bermaslik",ex:"Some governments deny people access to certain websites."},
      {w:"entitle",p:"verb",ipa:"/ɪnˈtaɪtl/",def:"(be entitled to) to have the right to have or do something",tr:"huquq bermoq",ex:"Citizens are entitled to privacy."},
      {w:"access",p:"noun",ipa:"/ˈækses/",def:"the opportunity or right to use something or see somebody or something",tr:"kirish huquqi / foydalanish imkoniyati",ex:"Hackers gained access to the government's computers."},
      {w:"to be sure",p:"phrase",ipa:"/tə bi ˈʃɔː(r)/",def:"(formal) used to admit that something is true before you make a different point",tr:"albatta / to'g'ri, lekin",ex:"To be sure, security is important, but so is freedom."},
      {w:"restrictive",p:"adjective",ipa:"/rɪˈstrɪktɪv/",def:"preventing people from doing what they want",tr:"cheklovchi",ex:"Some people think the new rules are too restrictive."}
